class Solution {
    public int findKthNumber(int n, int k) {
        long cur = 1;
        k--;
        while (k > 0) {
            long steps = countSteps(n, cur, cur + 1);
            if (steps <= k) { k -= steps; cur++; }
            else { k--; cur *= 10; }
        }
        return (int) cur;
    }
    private long countSteps(int n, long cur, long next) {
        long steps = 0;
        while (cur <= n) {
            steps += Math.min(n + 1, next) - cur;
            cur *= 10;
            next *= 10;
        }
        return steps;
    }
}

class Solution {
    public int findKthNumber(int n, int k) {
        long cur = 1;
        k--;
        while (k > 0) {
            long steps = getSteps(n, cur);
            if (steps <= k) {
                k -= (int) steps;
                cur++;
            } else {
                k--;
                cur *= 10;
            }
        }
        return (int) cur;
    }
    private long getSteps(int n, long prefix) {
        long steps = 0;
        long first = prefix;
        long last = prefix + 1;
        while (first <= n) {
            steps += Math.min((long) n + 1, last) - first;
            first *= 10;
            last *= 10;
        }
        return steps;
    }
}
